import dlarft = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const V = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const T = new Float64Array( 4 );
	dlarft( 'column-major', 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const V = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const T = new Float64Array( 4 );
	dlarft( 5, 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( true, 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( false, 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( null, 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( void 0, 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( [], 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( {}, 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( ( x: number ): number => x, 'forward', 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a valid direction...
{
	const V = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const T = new Float64Array( 4 );
	dlarft( 'column-major', 5, 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( 'column-major', true, 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( 'column-major', false, 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( 'column-major', null, 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( 'column-major', void 0, 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( 'column-major', [], 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( 'column-major', {}, 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
	dlarft( 'column-major', ( x: number ): number => x, 'columns', 3, 2, V, 3, TAU, T, 2 ); // $ExpectError
}

