// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const V = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const T = new Float64Array( 4 );
	dlarft(); // $ExpectError
	dlarft( 'column-major' ); // $ExpectError
	dlarft( 'column-major', 'forward' ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns' ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns', 3 ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns', 3, 2 ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns', 3, 2, V ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns', 3, 2, V, 3 ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns', 3, 2, V, 3, TAU ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns', 3, 2, V, 3, TAU, T ); // $ExpectError
	dlarft( 'column-major', 'forward', 'columns', 3, 2, V, 3, TAU, T, 2, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Float64Array...
{
	const V = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const T = new Float64Array( 4 );
	dlarft.ndarray( 'forward', 'columns', 3, 2, V, 1, 3, 0, TAU, 1, 0, T, 1, 2, 0 ); // $ExpectType Float64Array
}

